import React, { useState } from "react";
import axios from "axios";
import { Link, useNavigate } from "react-router-dom";

const Login = () => {

const navigate = useNavigate();

const [email,setEmail]=useState("");

const [password,setPassword]=useState("");

const [msg,setMsg]=useState("");

const handleLogin=async(e)=>{

e.preventDefault();

try{

const res=await axios.post(

"http://localhost:5000/api/auth/login",

{

email,

password

}

);

localStorage.setItem(

"token",

res.data.token

);

localStorage.setItem(

"user",

JSON.stringify(

res.data.user

)

);

setMsg(

"Login Successful ✅"

);

setTimeout(()=>{

navigate("/");

},1000);

}

catch(err){

setMsg(

err.response?.data?.message

||

"Login Failed ❌"

);

}

};

return(

<div

style={{

height:"100vh",

display:"flex",

justifyContent:"center",

alignItems:"center",

background:

"linear-gradient(to right,#667eea,#764ba2)"

}}

>

<form

onSubmit={handleLogin}

style={{

background:"#fff",

padding:"35px",

borderRadius:"20px",

width:"380px",

boxShadow:

"0 0 20px rgba(0,0,0,0.2)"

}}

>

<h1

style={{

textAlign:"center",

marginBottom:"20px"

}}

>

RBAC Login

</h1>


<input

type="email"

placeholder="Email"

value={email}

onChange={(e)=>

setEmail(e.target.value)

}

style={{

width:"100%",

padding:"12px",

marginBottom:"15px",

borderRadius:"8px",

border:"1px solid #ccc"

}}

required

/>


<input

type="password"

placeholder="Password"

value={password}

onChange={(e)=>

setPassword(e.target.value)

}

style={{

width:"100%",

padding:"12px",

marginBottom:"15px",

borderRadius:"8px",

border:"1px solid #ccc"

}}

required

/>


<button

type="submit"

style={{

width:"100%",

padding:"12px",

background:"#4f46e5",

color:"#fff",

border:"none",

borderRadius:"8px",

cursor:"pointer",

fontSize:"16px"

}}

>

Login

</button>


<p

style={{

marginTop:"20px",

textAlign:"center"

}}

>

New User ?

<Link to="/register">

 Register

</Link>

</p>


<h3

style={{

textAlign:"center",

color:"green"

}}

>

{msg}

</h3>

</form>

</div>

)

}

export default Login;
